import { onEveryTap } from './taps.ts';

/**
 * Recorded speech for a game. Generated by scripts/voice: `clips` maps each
 * spoken line to its file, and `slow` does the same for lines also recorded slowly.
 */
export interface ClipManifest {
  clips: Record<string, string>;
  slow?: Record<string, string>;
}

/** How a clip went: played to its end or was cut, was refused before a first tap, or would not load. */
export type ClipResult = 'played' | 'blocked' | 'failed';

/** Longer than a voice's limit, because a clip may have to come over a slow connection. */
const START_LIMIT_MS = 4000;

// A moment of nothing, played once inside a tap. iOS then lets this same element play later without one.
const SILENCE =
  'data:audio/mpeg;base64,';

let registered: { manifest: ClipManifest; baseUrl: string } | null = null;
// One element for every clip, because iOS unlocks an element, not a page.
let audio: HTMLAudioElement | null = null;
let unlocked = false;
let unlocking = false;
let playing = false;
const reported = new Set<string>();

function sharedAudio(): HTMLAudioElement | null {
  if (!audio && typeof Audio !== 'undefined') audio = new Audio();
  return audio;
}

function unlock(): void {
  const element = sharedAudio();
  if (!element || unlocked || unlocking || playing) return;
  unlocking = true;
  element.src = SILENCE;
  void Promise.resolve(element.play())
    .then(() => {
      unlocked = true;
    })
    // A clip starting in the same tap replaces the silence, which rejects this. The tap has still counted.
    .catch(() => {})
    .finally(() => {
      unlocking = false;
    });
}

/**
 * Registers a game's recorded lines. Calling this is also how a game says it
 * speaks Slovenian: a game that never does stays in English whatever the shared
 * language is, so a child never loses the voice in a game not yet translated.
 */
export function useClips(manifest: ClipManifest, baseUrl = './voice/sl/'): void {
  registered = { manifest, baseUrl };
  onEveryTap(unlock);
}

export function hasClips(): boolean {
  return registered !== null;
}

/** The address of a line's clip, preferring the slow recording when asked for one. */
export function clipUrl(text: string, slow = false): string | null {
  if (!registered) return null;
  const { manifest, baseUrl } = registered;
  const file =
    (slow && manifest.slow && Object.hasOwn(manifest.slow, text) ? manifest.slow[text] : undefined) ??
    (Object.hasOwn(manifest.clips, text) ? manifest.clips[text] : undefined);
  return file ? baseUrl + file : null;
}

/** Says once in development that a line had no working clip, so it gets noticed before a child does. */
export function reportMissingClip(text: string): void {
  if (!import.meta.env?.DEV || reported.has(text)) return;
  reported.add(text);
  console.warn(`Missing Slovenian clip: "${text}". Run npm run voice.`);
}

/** Lines with no clip. A game's test checks this is empty, so missing audio can't ship. */
export function missingClips(manifest: ClipManifest, lines: readonly string[], slow: readonly string[] = []): string[] {
  return [
    ...lines.filter((line) => !Object.hasOwn(manifest.clips, line)),
    ...slow.filter((line) => !Object.hasOwn(manifest.slow ?? {}, line)).map((line) => `(slow) ${line}`),
  ];
}

/**
 * Plays a clip on the shared element. It always settles: a clip that won't start
 * fails, and one that starts and never ends is cut at endLimitMs.
 */
export function playClip(url: string, signal: AbortSignal, endLimitMs: number): Promise<ClipResult> {
  const element = sharedAudio();
  if (!element) return Promise.resolve('failed');

  return new Promise((resolve) => {
    let settled = false;
    let limit: ReturnType<typeof setTimeout>;

    const finish = (result: ClipResult): void => {
      if (settled) return;
      settled = true;
      playing = false;
      clearTimeout(limit);
      signal.removeEventListener('abort', cut);
      element.removeEventListener('playing', started);
      element.removeEventListener('ended', ended);
      element.removeEventListener('error', failed);
      resolve(result);
    };
    const stopWith = (result: ClipResult): void => {
      if (settled) return;
      element.pause();
      finish(result);
    };
    const cut = (): void => stopWith('played');
    const failed = (): void => stopWith('failed');
    const ended = (): void => finish('played');
    const started = (): void => {
      unlocked = true;
      clearTimeout(limit);
      limit = setTimeout(cut, endLimitMs);
    };

    playing = true;
    signal.addEventListener('abort', cut, { once: true });
    element.addEventListener('playing', started);
    element.addEventListener('ended', ended);
    element.addEventListener('error', failed);
    limit = setTimeout(failed, START_LIMIT_MS);

    element.src = url;
    Promise.resolve(element.play()).catch((error: unknown) => {
      stopWith(error instanceof Error && error.name === 'NotAllowedError' ? 'blocked' : 'failed');
    });
  });
}
